static const unsigned char temp_binary_data_602[] =
"declare const stringWidth: {\n"
"\t/**\n"
"\tGet the visual width of a string - the number of columns required to display it.\n"
"\n"
"\tSome Unicode characters are [fullwidth](https://en.wikipedia.org/wiki/Halfwidth_and_fullwidth_forms) and use double the normal width. [ANSI escape codes](https://en.wikipedia.org/wiki/ANSI_escape_code) are stripped and doesn't affect the width.\n"
"\n"
"\t@example\n"
"\t```\n"
"\timport stringWidth = require('string-width');\n"
"\n"
"\tstringWidth('a');\n"
"\t//=> 1\n"
"\n"
"\tstringWidth('\xe5\x8f\xa4');\n"
"\t//=> 2\n"
"\n"
"\tstringWidth('\\u001B[1m\xe5\x8f\xa4\\u001B[22m');\n"
"\t//=> 2\n"
"\t```\n"
"\t*/\n"
"\t(string: string): number;\n"
"\n"
"\t// TODO: remove this in the next major version, refactor the whole definition to:\n"
"\t// declare function stringWidth(string: string): number;\n"
"\t// export = stringWidth;\n"
"\tdefault: typeof stringWidth;\n"
"}\n"
"\n"
"export = stringWidth;\n";

const char* index_d_ts40 = (const char*) temp_binary_data_602;

//================== index.js ==================
static const unsigned char temp_binary_data_603[] =
"'use strict';\n"
"const stripAnsi = require('strip-ansi');\n"
"const isFullwidthCodePoint = require('is-fullwidth-code-point');\n"
"const emojiRegex = require('emoji-regex');\n"
"\n"
"const stringWidth = string => {\n"
"\tif (typeof string !== 'string' || string.length === 0) {\n"
"\t\treturn 0;\n"
"\t}\n"
"\n"
"\tstring = stripAnsi(string);\n"
"\n"
"\tif (string.length === 0) {\n"
"\t\treturn 0;\n"
"\t}\n"
"\n"
"\tstring = string.replace(emojiRegex(), '  ');\n"
"\n"
"\tlet width = 0;\n"
"\n"
"\tfor (let i = 0; i < string.length; i++) {\n"
"\t\tconst code = string.codePointAt(i);\n"
"\n"
"\t\t// Ignore control characters\n"
"\t\tif (code <= 0x1F || (code >= 0x7F && code <= 0x9F)) {\n"
"\t\t\tcontinue;\n"
"\t\t}\n"
"\n"
"\t\t// Ignore combining characters\n"
"\t\tif (code >= 0x300 && code <= 0x36F) {\n"
"\t\t\tcontinue;\n"
"\t\t}\n"
"\n"
"\t\t// Surrogates\n"
"\t\tif (code > 0xFFFF) {\n"
"\t\t\ti++;\n"
"\t\t}\n"
"\n"
"\t\twidth += isFullwidthCodePoint(code) ? 2 : 1;\n"
"\t}\n"
"\n"
"\treturn width;\n"
"};\n"
"\n"
"module.exports = stringWidth;\n"
"// TODO: remove this in the next major version\n"
"module.exports.default = stringWidth;\n";

